Loss.create!([
  {date: "2016-04-12 04:00:00", amount: "21400000.0", title: "HB2 causes cancellation of Deutsche Bank's planned Cary expansion", slug: "deutsche-bank", description: "After freezing jobs expansion in Cary over HB2, Deutsche Bank moves ahead with Florida expansion", template: "\nThings just keep getting worse for the state of NC over HB2.<br><br>\n\nAccounting for nearly 8% of the total losses to the state of North Carolina to date, the  loss of this company expansion is yet another financial setback for the state over HB2.\n\n <blockquote class=\"template-quote\">\n\"\"We take the commitment to building inclusive work environments seriously. We’re proud of our operations and employees in Cary and regret that as a result of this legislation we are unwilling to include North Carolina in our U.S. expansion plans for now. We very much hope to revisit our plans to grow this location in the near future.\"\n<br><br>\n- John Cryan, Co-Chief Executive Officer of Deutsche Bank.\n <a class=\"link\" href=\"https://www.db.com/usa/content/en/3639.html\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe loss of the Deutsche Bank expansion is not only a loss for Cary, but for the state of North Carolina as a whole.\n", sources: [{"link"=>"http://www.bizjournals.com/triangle/news/2016/07/27/three-months-after-hb2-jobs-freeze-in-cary.html", "meta"=>{"publication"=>"Triangle Business Journal", "title"=>"After freezing jobs expansion in Cary over HB2, Deutsche Bank moves ahead with Florida expansion", "date"=>"7/27/16", "author"=>"Lauren K. Ohnesorge", "accessed"=>"9/9/16"}}, {"link"=>"http://www.newsobserver.com/news/business/article71314817.html", "meta"=>{"publication"=>"The News and Observer", "title"=>"Economic impact of HB2 mushrooms in the Triangle", "date"=>"4/12/16", "author"=>"David Bracken and Paul A. Specht", "accessed"=>"9/9/16"}}, {"link"=>"https://www.americanprogress.org/issues/lgbt/news/2016/04/13/135391/north-carolinas-discriminatory-h-b-2-threatens-more-than-half-billion-dollars-in-economic-activity/", "meta"=>{"publication"=>"Center for American Progress", "title"=>"North Carolina’s Discriminatory H.B. 2 Threatens More Than Half Billion Dollars in Economic Activity", "date"=>"4/13/16", "author"=>"Shabab Ahmed Mirza, Sarah McBride, Laura E. Durso", "accessed"=>"9/9/16"}}], active: true, featured: false, short_name: "Deutsche Bank", photo_credit: ""},
  {date: "2016-04-05 04:00:00", amount: "44000000.0", title: "PayPal withdraws NC investment over HB2", slug: "paypal", description: "", template: "\nThings just keep getting worse for the state of NC over HB2.<br><br>\n\nContributing  $44,000,000 to the total of $259,424,000, the loss of this company expansion is painful for NC.\n\n <blockquote class=\"template-quote\">\n\"\"The new law perpetuates discrimination and it violates the values and principles that are at the core of PayPal’s mission and culture.  As a result, PayPal will not move forward with our planned expansion into Charlotte.\"\n<br><br>\n- Dan Schulman, President and CEO of PayPal.\n <a class=\"link\" href=\"https://www.paypal.com/stories/us/paypal-withdraws-plan-for-charlotte-expansion\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThis is but one of many recent losses for the state of NC related to HB2.\n", sources: [{"link"=>"http://www.hrc.org/blog/am-equality-tip-sheet-april-5-2016", "meta"=>{"publication"=>"Human Rights Campaign", "title"=>"#AM_Equality Tip Sheet: April 5, 2016", "date"=>"4/5/2016", "author"=>"HRC Staff", "accessed"=>"9/9/16"}}, {"link"=>"https://www.americanprogress.org/issues/lgbt/news/2016/04/13/135391/north-carolinas-discriminatory-h-b-2-threatens-more-than-half-billion-dollars-in-economic-activity/", "meta"=>{"publication"=>"Center for American Progress", "title"=>"North Carolina’s Discriminatory H.B. 2 Threatens More Than Half Billion Dollars in Economic Activity", "date"=>"4/13/2016", "author"=>"Shabab Ahmed Mirza, Sarah McBride, Laura E. Durso", "accessed"=>"9/9/16"}}], active: true, featured: true, short_name: "PayPal", photo_credit: "Ken Wolter / Shutterstock.com"},
  {date: "2016-04-08 04:00:00", amount: "700000.0", title: "Bruce Springsteen concert cancelled in protest of House Bill 2", slug: "bruce-springsteen", description: "Springsteen was scheduled to play Greensboro, but said he finds the passing of House Bill 2 unacceptable, and he is doing his part to push back.", template: "\nThe state of North Carolina reports another loss due to HB2.<br><br>\n\nContributing  $700,000 to the total of $259,424,000, the loss of this concert is painful for NC.\n\n <blockquote class=\"template-quote\">\n\"\"Some things are more important than a rock show and this fight against prejudice and bigotry — which is happening as I write — is one of them. It is the strongest means I have for raising my voice in opposition to those who continue to push us backwards instead of forwards.\"\n<br><br>\n- Bruce Springsteen\n <a class=\"link\" href=\"http://brucespringsteen.net/news/2016/a-statement-from-bruce-springsteen-on-north-carolina\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe loss of the Bruce Springsteen concert marks yet another unnecessary loss for NC.\n", sources: [{"link"=>"http://money.cnn.com/2016/04/08/media/bruce-springsteen-north-carolina-show-canceled/", "meta"=>{"publication"=>"CNN Money", "title"=>"Bruce Springsteen cancels North Carolina concert over 'bathroom law'", "date"=>"4/8/16", "author"=>"Tom Kludt", "accessed"=>"9/9/16"}}, {"link"=>"https://www.americanprogress.org/issues/lgbt/news/2016/04/13/135391/north-carolinas-discriminatory-h-b-2-threatens-more-than-half-billion-dollars-in-economic-activity/", "meta"=>{"publication"=>"Center for American Progress", "title"=>"North Carolina’s Discriminatory H.B. 2 Threatens More Than Half Billion Dollars in Economic Activity", "date"=>"4/13/16", "author"=>"Shabab Ahmed Mirza, Sarah McBride, Laura E. Durso", "accessed"=>"9/9/16"}}], active: true, featured: true, short_name: "Bruce Springsteen", photo_credit: "Brian Patterson Photos / Shutterstock.com"},
  {date: "2016-04-04 04:00:00", amount: "3000000.0", title: "Lionsgate moves move shoot out of NC because of HB2", slug: "lionsgate", description: "", template: "\nNorth Carolina reports further HB2 related losses.<br><br>\n\nContributing  $3,000,000 to the total of $259,424,000, the loss of this movie shoot hurts North Carolina.\n\n <blockquote class=\"template-quote\">\n\"\"We will be hard pressed to continue our relationship with North Carolina if this regressive law remains on the books\"\n<br><br>\n- Lionsgatevia Charlotte Observer\n <a class=\"link\" href=\"http://www.charlotteobserver.com/news/business/article69837702.html\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThis is but one of many recent losses for the state of NC related to HB2.\n", sources: [{"link"=>"http://www.fox46charlotte.com/news/local-news/116956922-story", "meta"=>{"publication"=>"Fox 46 of Charlotte", "title"=>"Lionsgate takes 100 jobs from NC due to HB2", "date"=>"4/4/16", "author"=>"Fox", "accessed"=>"9/9/16"}}, {"link"=>"https://www.americanprogress.org/issues/lgbt/news/2016/04/13/135391/north-carolinas-discriminatory-h-b-2-threatens-more-than-half-billion-dollars-in-economic-activity/", "meta"=>{"publication"=>"Center for American Progress", "title"=>"North Carolina’s Discriminatory H.B. 2 Threatens More Than Half Billion Dollars in Economic Activity", "date"=>"4/13/16", "author"=>"Shabab Ahmed Mirza, Sarah McBride, Laura E. Durso", "accessed"=>"9/9/16"}}], active: true, featured: false, short_name: "Lionsgate", photo_credit: "Kobby Dagan / Shutterstock.com"},
  {date: "2016-07-21 04:00:00", amount: "100000000.0", title: "The NBA moves 2017 All-Star Game out of North Carolina in response to HB2", slug: "nba-all-star-game", description: "", template: "\nHere's another unfortunate loss for the state of North Carolina.<br><br>\n\nAccounting for nearly 39% of the total losses to the state of North Carolina to date, the  loss of this event is yet another financial setback for the state over HB2.\n\n <blockquote class=\"template-quote\">\n\"\"The NBA has decided to relocate the 2017 All-Star Game from Charlotte with the hope of rescheduling for 2019.\n\nSince March, when North Carolina enacted HB2 and the issue of legal protections for the LGBT community in Charlotte became prominent, the NBA and the Charlotte Hornets have been working diligently to foster constructive dialogue and try to effect positive change. We have been guided in these discussions by the long-standing core values of our league. These include not only diversity, inclusion, fairness and respect for others but also the willingness to listen and consider opposing points of view.\n\nOur week-long schedule of All-Star events and activities is intended to be a global celebration of basketball, our league, and the values for which we stand, and to bring together all members of the NBA community -- current and former players, league and team officials, business partners, and fans. While we recognize that the NBA cannot choose the law in every city, state, and country in which we do business, we do not believe we can successfully host our All-Star festivities in Charlotte in the climate created by HB2.\n\nWe are particularly mindful of the impact of this decision on our fans in North Carolina, and who are among the most passionate in our league. It is also important to stress that the City of Charlotte and the Hornets organization have sought to provide an inclusive environment and that the Hornets will continue to ensure that all patrons -- including members of the LGBT community -- feel welcome while attending games and events in their arena.\n\nWe look forward to re-starting plans for our All-Star festivities in Charlotte for 2019 provided there is an appropriate resolution to this matter.\n\nThe NBA will make an announcement on the new location of the 2017 NBA All-Star Game in the coming weeks.\"\n<br><br>\n- NBA\n</blockquote>\n\nThe NBA All-Star Game in Charlotte is just one of recent losses for NC over HB2.\n", sources: [{"link"=>"http://www.forbes.com/sites/maurybrown/2016/07/22/the-economic-impact-of-charlotte-losing-nba-all-star-game-and-potentially-super-bowls-due-to-hb2/#6e66e6633f60", "meta"=>{"publication"=>"Forbes", "title"=>"The Economic Impact Of Charlotte Losing NBA All-Star Game, And Potentially Super Bowls Due To HB2", "date"=>"7/22/16", "author"=>"Maury Brown", "accessed"=>"9/9/16"}}, {"link"=>"https://www.washingtonpost.com/news/sports/wp/2016/07/21/report-nba-will-move-2017-all-star-game-from-charlotte-to-new-orleans-over-hb2-law/", "meta"=>{"publication"=>"Washington Post", "title"=>"NBA will move 2017 All-Star Game from Charlotte over HB2 law", "date"=>"7/21/16", "author"=>"Tim Bontemps", "accessed"=>"9/9/16"}}, {"link"=>"http://www.espn.com/nba/story/_/id/17120170/nba-moving-all-star-game-charlotte-north-carolina-bill", "meta"=>{"publication"=>"ESPN", "author"=>"NBA", "title"=>"NBA moves 2017 All-Star Game from Charlotte over HB2 bill", "date"=>"7/22/16", "accessed"=>"9/9/16"}}], active: true, featured: true, short_name: "NBA All-Star Game", photo_credit: ""},
  {date: "2016-05-27 04:00:00", amount: "62500000.0", title: "Attendance decreased at NC's Highpoint Market in response to HB2", slug: "highpoint-market", description: "", template: "\nNorth Carolina bears the burden of more economic strain over HB2, the controversial \"bathroom bill\" law.<br><br>\n\nContributing a whopping $62,500,000 to the total of $259,424,000, the loss of this  is particularly painful for NC, accounting for 24.092% of the losses to date.\n\n <blockquote class=\"template-quote\">\n\"\"Read more here: http://www.charlotteobserver.com/news/business/article69837702.html#storylink=cpy\"\n<br><br>\n- \n <a class=\"link\" href=\"\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe loss of the Highpoint Market marks yet another unnecessary loss for North Carolina.\n", sources: [{"link"=>"http://www.bizjournals.com/triad/news/2016/05/27/high-point-market-attendance-figures-released.html", "meta"=>{"publication"=>"Triad Business Journal", "title"=>"High Point Market attendance figures released", "date"=>"5/27/16", "accessed"=>"9/9/16"}}, {"link"=>"http://www.hickoryrecord.com/news/crowd-thins-slightly-at-nc-furniture-market-after-lgbt-law/article_0063fe40-2429-11e6-bd3a-9baf79980be0.html", "meta"=>{"publication"=>"Hickory Record", "title"=>"Crowd thins slightly at NC furniture market after LGBT law", "date"=>"5/27/16", "accessed"=>"9/9/16"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "Highpoint Market", photo_credit: "Tinxi / Shutterstock.com"},
  {date: "2016-05-20 04:00:00", amount: "1640000.0", title: "Citing HB2, Maroon 5 cancels NC shows", slug: "maroon-5", description: "", template: "\nNC loses even more money due to HB2.<br><br>\n\nAccounting for nearly 1% of the total losses to the state of North Carolina to date, the  loss of this concert is yet another financial setback for the state over HB2.\n\n <blockquote class=\"template-quote\">\n\"\"\"\n<br><br>\n- \n</blockquote>\n\nThis is but one of many recent losses for the state of NC related to HB2.\n", sources: [{"link"=>"http://www.wral.com/maroon-5-cancels-nc-shows-citing-hb2/15716462/", "meta"=>{"publication"=>"WRAL", "title"=>"Citing HB2, Maroon 5 cancels shows in Raleigh and Charlotte", "date"=>"5/20/16", "accessed"=>"9/9/16"}}, {"link"=>"http://www.charlotteobserver.com/entertainment/music-news-reviews/article78823022.html", "meta"=>{"publication"=>"Charlotte Observer", "title"=>"Maroon 5 cancels N.C. shows over HB2, calling decision ‘morally right", "date"=>"5/20/16", "accessed"=>"9/9/16", "author"=>"Theoden Janes"}}, {"link"=>"CUSTOM_CALC", "anchor"=>true}], active: true, featured: false, short_name: "Maroon 5", photo_credit: "FashionStock.com / Shutterstock.com"},
  {date: "2016-05-17 04:00:00", amount: "74000.0", title: "Itzhak Perlman cancels NC concert in protest of HB2", slug: "itzhak-perlman", description: "", template: "\nThe state of North Carolina reports another loss due to HB2.<br><br>\n\nAccounting for nearly 0% of the total losses to the state of North Carolina to date, the  loss of this  is yet another financial setback for the state over HB2.\n\n <blockquote class=\"template-quote\">\n\"\"As my fans know, I have spent a lifetime advocating against discrimination towards those with physical disabilities and have been a vocal advocate for treating all people equally. As such, after great consideration, I have decided to cancel my May 18th concert in North Carolina with the North Carolina Symphony as a stand against House Bill 2. As Attorney General Loretta Lynch recently stated, and HB2 “is about a great deal more than just bathrooms. [It] is about the dignity and respect we accord our fellow citizens.” I couldn’t agree more and will look forward to returning to North Carolina when this discriminatory law is repealed.\"\n<br><br>\n- Itzhak Perlmanvia Facebook\n</blockquote>\n\nThe state continues to lose money over HB2.\n", sources: [{"link"=>"http://www.jewishjournal.com/culture/article/violinist_itzhak_perlman_scraps_n.c._concert_over_discriminatory_law", "meta"=>{"publication"=>"Jewish Journal", "title"=>"Violinist Itzhak Perlman scraps N.C. concert over ‘discriminatory’ law", "date"=>"5/17/16", "accessed"=>"9/9/16", "author"=>"Colleen Jenkins"}}, {"link"=>"http://www.npr.org/sections/deceptivecadence/2016/05/18/478556368/itzhak-perlman-on-canceling-in-north-carolina-i-had-to", "meta"=>{"publication"=>"NPR", "title"=>"Itzhak Perlman On Canceling In North Carolina: 'I Had To'", "date"=>"5/18/16", "accessed"=>"9/9/16", "author"=>"Anastasia Tsioulcas"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "Itzhak Perlman", photo_credit: "Roman Yanushevsky / Shutterstock.com"},
  {date: "2016-04-26 04:00:00", amount: "1500000.0", title: "Due to HB2, W. K. Kellogg Foundation conference moved out of Asheville", slug: "w-k-kellogg", description: "", template: "\nNorth Carolina bears the burden of more economic strain over HB2, the controversial \"bathroom bill\" law.<br><br>\n\nAccounting for nearly 1% of the total losses to the state of North Carolina to date, the  loss of this  is a painful reality for the state.\n\n <blockquote class=\"template-quote\">\n\"\"\"\n<br><br>\n- \n</blockquote>\n\nThe state continues to lose money over HB2.\n", sources: [{"link"=>"http://www.citizen-times.com/story/news/local/2016/04/25/hb2-costs-asheville-15m-conference/83513046/", "meta"=>{"publication"=>"Citizen Times", "title"=>"HB2 costs Asheville $1.5M conference", "date"=>"4/26/16", "accessed"=>"9/9/16", "author"=>"John Boyle"}}, {"link"=>"http://wlos.com/news/local/asheville-conference-estimated-to-have-15-million-impact-canceled-due-to-hb2", "meta"=>{"publication"=>"News 13 WLOS", "title"=>"Asheville conference estimated to have $1.5 million impact canceled due to HB2", "date"=>"4/25/16", "accessed"=>"9/9/16", "author"=>"Kimberly King and Krystyna Biassou"}}], active: true, featured: true, short_name: "W. K. Kellogg Foundation", photo_credit: ""},
  {date: "2016-04-25 04:00:00", amount: "950000.0", title: "American Institute of Architects moves South Atlantic Region Conference out of Wilmington because of HB2", slug: "aia", description: "", template: "\nNC continues to lose money due to the controversial House Bill 2.<br><br>\n\nContributing  $950,000 to the total of $259,424,000, the loss of this  is painful for NC.\n\n <blockquote class=\"template-quote\">\n\"\"\"\n<br><br>\n- \n</blockquote>\n\nThe loss of the AIA Conference marks yet another unnecessary loss for North Carolina.\n", sources: [{"link"=>"http://www.wilmingtonbiz.com/hospitality/2016/04/26/hb2_loss_of_architect_conference_costs_wilmington_nearly_1m_estimates_show/14705", "meta"=>{"publication"=>"Wilmington Biz", "title"=>"HB2 Loss Of Architect Conference Costs Wilmington Nearly $1M, Estimates Show", "date"=>"4/26/16", "accessed"=>"9/9/16", "author"=>"Cece Nunn"}}, {"link"=>"http://www.aianc.org/government-updates/hb2-our-commitment-to-diversity-and-inclusionary-design-1", "meta"=>{"publication"=>"AIA NC", "title"=>"AIA South Atlantic to Move Conference From Wilmington Due to HB 2", "date"=>"4/25/16", "accessed"=>"9/9/16", "author"=>"David Crawford"}}], active: true, featured: false, short_name: "AIA Conference", photo_credit: ""},
  {date: "2016-04-25 04:00:00", amount: "911000.0", title: "Demi Lovato and Nick Jonas cancel NC concerts in response to HB2", slug: "demi-lovato-nick-jonas", description: "", template: "\nNC continues to lose money due to the controversial House Bill 2.<br><br>\n\nContributing  $911,000 to the total of $259,424,000, the loss of this concert is painful for NC.\n\n <blockquote class=\"template-quote\">\n\"\"After much thought and deliberation, we have decided to cancel our Honda Civic Tour: Future Now shows in Raleigh and Charlotte. One of our goals for the tour has always been to create an atmosphere where every single attendee feels equal, included, and accepted for who they are.\"\n<br><br>\n- Demi Lovato and Nick Jonasvia Twitter\n <a class=\"link\" href=\"https://twitter.com/ddlovato/status/724705165186457600\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe loss of the Demi Lovato and Nick Jonas marks yet another unnecessary loss for NC.\n", sources: [{"link"=>"http://www.rollingstone.com/music/news/nick-jonas-demi-lovato-cancel-north-carolina-shows-to-protest-hb2-20160425", "meta"=>{"publication"=>"Rolling Stone", "title"=>"Nick Jonas, Demi Lovato Cancel North Carolina Shows to Protest HB2", "date"=>"4/25/16", "accessed"=>"9/9/16", "author"=>"Daniel Kreps"}}, {"link"=>"http://www.charlotteobserver.com/entertainment/music-news-reviews/article73823087.html", "meta"=>{"publication"=>"Charlotte Observer", "title"=>"Demi Lovato, Nick Jonas Charlotte show canceled over HB2", "date"=>"4/25/16", "accessed"=>"9/9/16", "author"=>"Mark Price"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "Demi Lovato and Nick Jonas", photo_credit: ""},
  {date: "2016-04-22 04:00:00", amount: "337000.0", title: "Blue Man Group cancels North Carolina shows to protest HB2", slug: "blue-man-group", description: "", template: "\nNorth Carolina reports further HB2 related losses.<br><br>\n\nContributing  $337,000 to the total of $259,424,000, the loss of this show hurts North Carolina.\n\n <blockquote class=\"template-quote\">\n\"\"We value every individual’s right to live a dignified, vibrant life in full color. As such, we are joining the growing list of entertainment professionals in protest of North Carolina’s HB2 law by canceling our upcoming tour performances in Charlotte.\"\n<br><br>\n- Blue Man Group\n <a class=\"link\" href=\"\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe loss of the Blue Man Group is just one of many recent HB2 related economic downfalls affecting the state of North Carolina.\n", sources: [{"link"=>"http://www.wral.com/blue-man-group-latest-group-to-cancel-show-over-hb2/15658384/", "meta"=>{"publication"=>"WRAL", "title"=>"Blue Man Group latest performers to cancel show over HB2", "date"=>"4/22/16", "accessed"=>"9/10/16"}}, {"link"=>"http://wncn.com/2016/04/22/blue-man-group-cancels-charlotte-performance-citing-hb2/", "meta"=>{"publication"=>"WNCN", "title"=>"Blue Man Group cancels Charlotte performance citing HB2", "date"=>"4/22/16", "accessed"=>"9/10/16"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "Blue Man Group", photo_credit: "360b / Shutterstock.com"},
  {date: "2016-04-18 04:00:00", amount: "1700000.0", title: "Community Transporation Association of America pulls out of NC over HB2", slug: "ctaa", description: "", template: "\nNorth Carolina reports further HB2 related losses.<br><br>\n\nAccounting for nearly 1% of the total losses to the state of North Carolina to date, the  loss of this convention is yet another financial setback for the state over HB2.\n\n <blockquote class=\"template-quote\">\n\"\"It's very significant. They were using five of our hotels, and it was a four day convention, so not only are the hotels being impacted, but restaurants, retail establishments, transportation companies. Everyone is going to feel the heat on this.\"\n<br><br>\n- Denny Edwards, CEO, Greater Raleigh Conventions and Visitor's Bureau.\n <a class=\"link\" href=\"http://abc11.com/news/raleigh-business-owner-fears-hb2-shutting-out-customers/1297766/\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe Community Transportation Association of America Event in Raleigh is just one of recent losses for NC over HB2.\n", sources: [{"link"=>"http://www.newsobserver.com/news/business/article72440452.html", "meta"=>{"publication"=>"News and Observer", "title"=>"HB2 has quadrupled economic losses", "date"=>"4/18/16", "accessed"=>"9/10/16", "author"=>"Paul A. Specht"}}, {"link"=>"http://associationsnow.com/2016/04/hb2-costing-north-carolina-business-convention-bureaus-warn/", "meta"=>{"publication"=>"Associations Now", "title"=>"HB2 costing North Carolina business, convention bureaus warn", "date"=>"4/19/16", "accessed"=>"9/10/16", "author"=>"Ernie Smith"}}], active: true, featured: false, short_name: "Community Transportation Association of America", photo_credit: ""},
  {date: "2016-04-18 04:00:00", amount: "191000.0", title: "Record Store Day moved from Raleigh to Baltimore over HB2", slug: "record-store-day", description: "", template: "\nNorth Carolina bears the burden of more economic strain over HB2, the controversial \"bathroom bill\" law.<br><br>\n\nAccounting for nearly 0% of the total losses to the state of North Carolina to date, the  loss of this  is a painful reality for the state.\n\n <blockquote class=\"template-quote\">\n\"\"We look forward to showing off Raleigh and the true spirit of North Carolina after the repeal of HB2.\n\n\"\n<br><br>\n- Carrie Colliton, Director of Marketing, Department of Record Stores, and co-founder of Record Store Day.\n <a class=\"link\" href=\"\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe state continues to lose money over HB2.\n", sources: [{"link"=>"http://www.newsobserver.com/news/business/article72440452.html", "meta"=>{"publication"=>"News and Observer", "title"=>"HB2 has quadrupled economic losses", "date"=>"4/18/16", "accessed"=>"9/10/16", "author"=>"Paul A. Specht"}}, {"link"=>"http://www.dailykos.com/story/2016/4/19/1517370/-NC-s-HB2-The-Hits-Just-Keep-On-Rolling", "meta"=>{"publication"=>"Daily Kos", "title"=>"NC's HB2 - The Hits Just Keep On Rolling....", "date"=>"4/19/16", "accessed"=>"9/10/16", "author"=>"Lamont Cranston"}}], active: true, featured: false, short_name: "Record Store Day", photo_credit: "DutchScenery / Shutterstock.com"},
  {date: "2016-04-18 04:00:00", amount: "1100000.0", title: "Boston cancels 3 North Carolina shows on their tour to raise awareness about HB2", slug: "boston", description: "", template: "\nNC loses even more money due to HB2.<br><br>\n\nAccounting for nearly 0% of the total losses to the state of North Carolina to date, the  loss of this concert is but one of many recent hits related to HB2.\n\n <blockquote class=\"template-quote\">\n\"\"While the enjoyment of our fans is our central concern, and we have been looking forward to celebrating forty years of history performing for our listeners in North Carolina with spectacular live shows this spring, human rights are more important.\"\n<br><br>\n- Tom Scholzvia Facebook\n <a class=\"link\" href=\"https://www.facebook.com/bandboston/posts/1176004065772990\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe Boston in Raleigh, Charlotte, and and Greensboro is just one of recent losses for NC over HB2.\n", sources: [{"link"=>"http://www.thetimesnews.com/news/20160418/boston-cancels-three-north-carolina-shows", "meta"=>{"publication"=>"Times News", "title"=>"Boston cancels three North Carolina shows", "date"=>"4/18/16", "accessed"=>"9/10/16"}}, {"link"=>"http://www.charlotteobserver.com/news/business/article72455377.html", "meta"=>{"publication"=>"Charlotte Observer", "title"=>"Boston cancels North Carolina shows because of LGBT law", "date"=>"4/18/16", "accessed"=>"9/10/16", "author"=>"Katherine Peralta"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "Boston", photo_credit: ""},
  {date: "2016-04-18 04:00:00", amount: "706000.0", title: "Pearl Jam cancels show, citing HB2", slug: "pearl-jam", description: "", template: "\nNC loses even more money due to HB2.<br><br>\n\nContributing  $706,000 to the total of $259,424,000, the loss of this  hurts North Carolina.\n\n <blockquote class=\"template-quote\">\n\"\"The HB2 law that was recently passed is a despicable piece of legislation that encourages discrimination against an entire group of American citizens. The practical implications are expansive and its negative impact upon basic human rights is profound.\"\n<br><br>\n- Pearl Jam\n <a class=\"link\" href=\"https://pearljam.com/news/north-carolina-concert-cancelled\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe loss of the Pearl Jam marks yet another unnecessary loss for NC.\n", sources: [{"link"=>"http://www.rollingstone.com/music/news/pearl-jam-cancel-raleigh-concert-to-oppose-bathroom-bill-20160418", "meta"=>{"publication"=>"Rolling Stone", "title"=>"Pearl Jame cancel Raleigh concert to oppose 'Bathroom Bill'", "date"=>"4/18/16", "accessed"=>"9/10/16", "author"=>"Daniel Kreps"}}, {"link"=>"http://www.bbc.com/news/world-us-canada-36079415", "meta"=>{"publication"=>"BBC", "title"=>"Pearl Jam cancel North Carolina concert over HB2 law", "date"=>"4/19/16", "accessed"=>"9/10/16"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "Pearl Jam", photo_credit: "Matteo Chinellato / Shutterstock.com"},
  {date: "2016-04-15 04:00:00", amount: "9536000.0", title: "Cirque du Soleil pulls NC stops off 2016 tour, citing HB2", slug: "cirque-du-soleil", description: "", template: "\nThe state of North Carolina reports another loss due to HB2.<br><br>\n\nContributing  $9,536,000 to the total of $259,424,000, the loss of this show hurts North Carolina.\n\n <blockquote class=\"template-quote\">\n\"\"Cirque du Soleil strongly believes in diversity and equality for every individual and is opposed to discrimination in any form. The new HB2 legislation passed in North Carolina is an important regression to ensuring human rights for all.\"\n<br><br>\n- Cirque du Soleilvia Facebook\n <a class=\"link\" href=\"https://www.facebook.com/notes/cirque-du-soleil/cirque-du-soleil-will-not-perform-in-north-carolina/10153690474037675\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe Cirque du Soleil in Raleigh, Charlotte, and and Greensboro is just one of recent losses for NC over HB2.\n", sources: [{"link"=>"https://www.washingtonpost.com/news/post-nation/wp/2016/04/15/cirque-du-soleil-cancels-north-carolina-shows-to-protest-lgbt-law/", "meta"=>{"publication"=>"Washington Post", "title"=>"Cirque du Soleil cancels North Carolina shows to protest LGBT law", "date"=>"4/15/16", "accessed"=>"9/10/16", "author"=>"Elahe Izadi"}}, {"link"=>"http://www.wral.com/cirque-du-soleil-cancels-nc-shows-over-hb2/15644282/", "meta"=>{"publication"=>"WRAL", "title"=>"Cirque du Soleil latest to cancel NC shows in protest of HB2", "date"=>"4/15/16", "accessed"=>"9/10/16", "author"=>"Arielle Clay"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "Cirque du Soleil", photo_credit: "Ververidis Vasilis / Shutterstock.com"},
  {date: "2016-04-13 04:00:00", amount: "348000.0", title: "Ringo Starr cancels NC show in opposition to HB2", slug: "ringo-starr", description: "", template: "\nThings just keep getting worse for the state of NC over HB2.<br><br>\n\nAccounting for nearly 0% of the total losses to the state of North Carolina to date, the  loss of this concert is a painful reality for the state.\n\n <blockquote class=\"template-quote\">\n\"\"I'm sorry to disappoint my fans in the area, but we need to take a stand against this hatred. Spread peace and love.\"\n<br><br>\n- Ringo Starr\n <a class=\"link\" href=\"http://ymlp.com/zPpUDv\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe state continues to lose money over HB2.\n", sources: [{"link"=>"http://www.washingtontimes.com/news/2016/apr/13/ringo-star-cancels-north-carolina-concert-protest-/", "meta"=>{"publication"=>"Washington Times", "title"=>"Ringo Starr cancels North Carolina concert in protest of transgender bathroom law", "date"=>"4/13/16", "accessed"=>"9/10/16", "author"=>"Bradford Richardson"}}, {"link"=>"http://www.newsweek.com/ringo-starr-cancels-north-carolina-concert-opposition-hb2-bill-447667", "meta"=>{"publication"=>"Newsweek", "title"=>"Ringo Starr cancels North Carolina concert in opposition to HB2 'bathroom' law", "date"=>"4/14/16", "accessed"=>"9/10/16", "author"=>"Tufayel Ahmed"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "Ringo Starr", photo_credit: "Featureflash Photo Agency / Shutterstock.com"},
  {date: "2016-04-06 04:00:00", amount: "1000.0", title: "Duck PD cancels spring conference due to HB2", slug: "duck-pd", description: "", template: "\nNC continues to lose money due to the controversial House Bill 2.<br><br>\n\nAccounting for nearly 0% of the total losses to the state of North Carolina to date, the  loss of this conference is yet another financial setback for the state over HB2.\n\n <blockquote class=\"template-quote\">\n\"\"\"\n<br><br>\n- \n</blockquote>\n\nThis is but one of many recent losses for the state of NC related to HB2.\n", sources: [{"link"=>"http://outerbanksvoice.com/2016/04/06/hb2-results-in-cancellation-of-duck-p-d-sponsored-conference/", "meta"=>{"publication"=>"Outer Banks Voice", "title"=>"HB2 results in cancellation of Duck P.D.-sponsored conference", "date"=>"4/6/16", "accessed"=>"9/10/16", "author"=>"Russ Lay"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "Duck Police Department", photo_credit: ""},
  {date: "2016-04-08 04:00:00", amount: "180000.0", title: "Southern Sociological Society moves 2019 annual meeting out of Charlotte", slug: "southern-sociological-society", description: "", template: "\nNorth Carolina bears the burden of more economic strain over HB2, the controversial \"bathroom bill\" law.<br><br>\n\nAccounting for nearly 0% of the total losses to the state of North Carolina to date, the  loss of this convention is a painful reality for the state.\n\n <blockquote class=\"template-quote\">\n\"\"We don’t want to spend our money in a state that discriminates against the L.G.B.T. community, and since our members often bring their families along to the conferences and stay in the destination for a few days after for fun, we’re talking about tourist dollars from airfare, hotel rooms and meals not going to Charlotte.\"\n<br><br>\n- Dr. Barbara Risman, former President of the Southern Sociological Society.\n <a class=\"link\" href=\"\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe loss of the Southern Sociological Society is not only a loss for Charlotte, but for the state of North Carolina as a whole.\n", sources: [{"link"=>"http://www.nytimes.com/2016/04/22/travel/north-carolina-mississippi-lgbt-gay-rights-travel.html", "meta"=>{"publication"=>"New York Times", "title"=>"North Carolina and Mississippi See Tourist Backlash After L.G.B.T. Laws", "date"=>"4/22/16", "accessed"=>"9/10/16", "author"=>"Shivani Vora"}}, {"link"=>"http://www.charlotteobserver.com/news/local/article70867152.html", "meta"=>{"publication"=>"Charlotte Observer", "title"=>"13 groups drop plans for Charlotte events, more could come over HB2", "date"=>"4/8/16", "accessed"=>"9/10/16", "author"=>"David Perlmutt"}}], active: true, featured: false, short_name: "Southern Sociological Society", photo_credit: ""},
  {date: "2016-07-13 04:00:00", amount: "1035000.0", title: "Duke vs. Albany Basketball game cancelled over HB2", slug: "duke-vs-albany-basketball", description: "", template: "\nNC continues to lose money due to the controversial House Bill 2.<br><br>\n\nContributing  $1,035,000 to the total of $259,424,000, the loss of this event is painful for NC.\n\n <blockquote class=\"template-quote\">\n\"\"The State University of New York supports Governor Cuomo's executive order banning all non-essential travel to the state of North Carolina.\"\n<br><br>\n- Holly Liapsis, SUNY spokesperson.\n <a class=\"link\" href=\"\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe Duke Basketball vs. Albany in Durham is just one of recent losses for NC over HB2.\n", sources: [{"link"=>"http://www.si.com/college-basketball/2016/07/13/albany-duke-canceled-governor-andrew-cuomo-north-carolina-bathroom-law", "meta"=>{"publication"=>"Sports Illustrated", "title"=>"Albany game at Duke canceled over North Carolina HB2 law", "date"=>"7/13/16", "accessed"=>"9/10/16"}}, {"link"=>"http://www.dukechronicle.com/article/2016/07/house-bill-2-leads-to-holes-in-duke-mens-basketball-field-hockey-schedules", "meta"=>{"publication"=>"Duke Chronicle", "title"=>"House Bill 2 leads to holes in Duke men's basketball, field hockey schedules", "date"=>"7/14/16", "accessed"=>"9/10/16"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "Duke vs. Albany", photo_credit: "Katherine Welles / Shutterstock.com"},
  {date: "2016-06-27 04:00:00", amount: "890000.0", title: "CSTE moves 2017 conference out of NC citing politics and travel bans to the state", slug: "cste", description: "", template: "\nNC loses even more money due to HB2.<br><br>\n\nContributing  $890,000 to the total of $259,424,000, the loss of this convention hurts North Carolina.\n\n <blockquote class=\"template-quote\">\n\"\"While CSTE historically hosts the conference in the state of its current president, the location announcement for 2017 remains on hold, pending the repeal or amendment of North Carolina’s March 2016 House Bill 2.\"\n<br><br>\n- CSTE, group.\n <a class=\"link\" href=\"http://www.csteconference.org/2016/2017-conference-location/\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe Council of State and Territorial Epidemiologists in Raleigh is just one of recent losses for NC over HB2.\n", sources: [{"link"=>"http://www.wral.com/news/local/page/15643947/", "meta"=>{"publication"=>"WRAL", "title"=>"At a glance: Economic impacts of HB2", "accessed"=>"9/13/16"}}, {"link"=>"http://www.csteconference.org/2016/2017-conference-location/", "meta"=>{"publication"=>"CSTE", "title"=>"2017 Conference Location", "date"=>"7/27/16", "accessed"=>"9/13/16"}}], active: true, featured: false, short_name: "Council of State and Territorial Epidemiologists", photo_credit: ""},
  {date: "2016-04-18 04:00:00", amount: "54000.0", title: "ALSC cancels it's 2016 National Institute in Charlotte in protest of HB2", slug: "alsc", description: "", template: "\nHere's another unfortunate loss for the state of North Carolina.<br><br>\n\nContributing  $54,000 to the total of $259,424,000, the loss of this conference hurts North Carolina.\n\n <blockquote class=\"template-quote\">\n\"\"The law contradicts the core values, purpose, and diversity work of ALSC and undermines civil rights and the fundamental principles upon which libraries are founded.\"\n<br><br>\n- ALSC\n <a class=\"link\" href=\"\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThis is but one of many recent losses for the state of NC related to HB2.\n", sources: [{"link"=>"http://www.charlotteobserver.com/news/business/article72635277.html", "meta"=>{"accessed"=>"9/16/16", "publication"=>"Charlotte Observer", "title"=>"Library group cancels 2016 meetings in Charlotte because of HB2", "author"=>"Katherine Peralta", "date"=>"4/19/16"}}, {"link"=>"https://americanlibrariesmagazine.org/blogs/the-scoop/alsc-board-votes-cancel-national-institute-charlotte/", "meta"=>{"accessed"=>"9/16/16", "date"=>"4/18/16", "publication"=>"American Libraries Magazine", "title"=>"ALSC Board Votes to Cancel National Institute in Charlotte"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "Association for Library Service to Children ", photo_credit: "American Libraries Magazine"},
  {date: "2016-09-12 04:00:00", amount: "5000000.0", title: "American Physical Society relocates 2018 conference to Florida in response to House Bill 2", slug: "american-physical-society", description: "", template: "\nThings just keep getting worse for the state of NC over HB2.<br><br>\n\nAccounting for nearly 2% of the total losses to the state of North Carolina to date, the  loss of this conference is yet another financial setback for the state over HB2.\n\n <blockquote class=\"template-quote\">\n\"\"Although we were unhappy that withdrawing from Charlotte would punish the city whose ordinance precipitated HB2, we felt that it was imperative DAMOP and the APS provide a welcoming environment for all members.\"\n<br><br>\n- Steven Rolston, DAMOP Chair.\n <a class=\"link\" href=\"\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThis is but one of many recent losses for the state of NC related to HB2.\n", sources: [{"link"=>"http://www.wral.com/news/local/page/15643947/", "meta"=>{"publication"=>"WRAL", "title"=>"At a glance: Economic impacts of HB2", "accessed"=>"9/13/16"}}, {"link"=>"http://www.charlotteobserver.com/news/politics-government/article93751152.html", "meta"=>{"publication"=>"Charlotte Observer", "title"=>"Citing HB2, American Physical Society moves 2018 meeting from Charlotte", "date"=>"8/4/16", "accessed"=>"9/13/16", "author"=>"Steve Harrison"}}, {"link"=>"http://www.aps.org/newsroom/pressreleases/08042016.cfm", "meta"=>{"publication"=>"APS Physics", "title"=>"Discriminatory North Carolina Restroom Law Prompts Major Scientific Society to Move Annual Meeting", "date"=>"8/4/16", "accessed"=>"9/13/16", "author"=>"James Riordon"}}], active: true, featured: false, short_name: "American Physical Society", photo_credit: ""},
  {date: "2016-05-26 04:00:00", amount: "693000.0", title: "Citizen Science Association moves it's 2017 convention out of Raleigh over HB2", slug: "csa", description: "", template: "\nHere's another unfortunate loss for the state of North Carolina.<br><br>\n\nContributing  $693,000 to the total of $259,424,000, the loss of this convention is painful for NC.\n\n <blockquote class=\"template-quote\">\n\"\"Our decision was based on our firm belief that our conferences ought to be held in locations and in ways that welcome all people into a safe space to discuss and advance the field of citizen science. \"\n<br><br>\n- Greg Newman, CSA Board Chair.\n <a class=\"link\" href=\"http://citizenscience.org/2016/05/26/in-support-of-our-core-values-a-conference-decision/\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe loss of the Citizen Science Association is just one of many recent HB2 related economic downfalls affecting the state of North Carolina.\n", sources: [{"link"=>"http://www.wral.com/news/local/page/15643947/", "meta"=>{"accessed"=>"9/13/16", "publication"=>"WRAL", "title"=>"At a glance: Economic impacts of HB2"}}, {"link"=>"http://citizenscience.org/2016/05/06/seeking-community-input-regarding-a-conference-conundrum/", "meta"=>{"accessed"=>"9/13/16", "publication"=>"Citizen Science", "title"=>"Seeking Community Input Regarding a Conference Conundrum", "date"=>"5/06/16"}}], active: true, featured: false, short_name: "Citizen Science Association", photo_credit: ""},
  {date: "2016-09-13 04:00:00", amount: "300000.0", title: "U.S. Association of Collegiate Fencing Clubs moves 2017 championship out of Winston-Salem", slug: "us-association-of-collegiate-fencing-clubs", description: "", template: "\nThings just keep getting worse for the state of NC over HB2.<br><br>\n\nAccounting for nearly 0% of the total losses to the state of North Carolina to date, the  loss of this event is but one of many recent hits related to HB2.\n\n <blockquote class=\"template-quote\">\n\"\"\"\n<br><br>\n- \n</blockquote>\n\nThe state continues to lose money over HB2.\n", sources: [{"link"=>"http://www.hickoryrecord.com/news/ncaa-moving---championships-from-north-carolina-over-hb/article_b1e6c176-79b9-11e6-8382-0b1e9c7435ed.html", "meta"=>{"accessed"=>"9/16/16", "publication"=>"Hickory Record", "title"=>"NCAA moving 2016-17 championships from North Carolina over HB2, civil rights protections", "author"=>"Jeff Mills", "date"=>"9/13/16"}}, {"link"=>"http://www.journalnow.com/news/local/forsyth-county-could-feel-ncaa-championship-ripple-effect-in-long/article_74762b70-ce7e-5492-8756-b6c807a8e30d.html", "meta"=>{"accessed"=>"9/16/16", "date"=>"9/13/16", "publication"=>"Winston-Salem Journal", "author"=>"Richard Craver", "title"=>"Forsyth County could feel NCAA championship ripple effect in long term"}}], active: true, featured: false, short_name: "U.S. Association of Collegiate Fencing Clubs", photo_credit: ""},
  {date: "2016-04-06 04:00:00", amount: "208000.0", title: "Oregon based Johnstone supply cancels Raleigh meeting over HB2", slug: "johnstone-supply", description: "", template: "\nThings just keep getting worse for the state of NC over HB2.<br><br>\n\nContributing  $208,000 to the total of $259,424,000, the loss of this conference hurts North Carolina.\n\n <blockquote class=\"template-quote\">\n\"\"We just felt that it’s not in the best interest of our membership to go someplace that’s not inclusive.\"\n<br><br>\n- Janet Tipton, Director of Communications, Johnstone Supply.\n <a class=\"link\" href=\"\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe Johnstone Supply in Raleigh is just one of recent losses for NC over HB2.\n", sources: [{"link"=>"http://www.wral.com/news/local/page/15643947/", "meta"=>{"accessed"=>"9/14/16", "publication"=>"WRAL", "title"=>"At a glance: Economic impacts of HB2"}}, {"link"=>"http://www.newsobserver.com/news/business/article71223992.html", "meta"=>{"accessed"=>"9/14/16", "author"=>"Paul A. Specht", "date"=>"4/11/16", "publication"=>"News and Observer", "title"=>"Raleigh visitors bureau says HB2 is affecting Wake economy"}}], active: true, featured: false, short_name: "Johnstone Supply", photo_credit: ""},
  {date: "2016-09-14 04:00:00", amount: "0.0", title: "Citing HB2, ACC moves 10 games out of North Carolina", slug: "acc", description: "", template: "\nThings just keep getting worse for the state of NC over HB2.<br><br>\n\nContributing  $0 to the total of $259,424,000, the loss of this event is painful for NC.\n\n <blockquote class=\"template-quote\">\n\"\"As members of the Atlantic Coast Conference, the ACC Council of Presidents reaffirmed our collective commitment to uphold the values of equality, diversity, inclusion and non-discrimination.\"\n<br><br>\n- ACC Council of Presidents\n <a class=\"link\" href=\"http://www.theacc.com/news/statements-from-the-atlantic-coast-conference-09-14-2016\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe ACC in  is just one of recent losses for NC over HB2.\n", sources: [{"link"=>"http://www.nytimes.com/2016/09/15/sports/acc-championships-north-carolina-hb2.html", "meta"=>{"accessed"=>"9/17/16", "author"=>"Marc Tracy and Alan Binder", "date"=>"9/14/16", "publication"=>"New York Times", "title"=>"A.C.C. Pulls League Championships Out of North Carolina"}}, {"link"=>"http://www.espn.com/college-football/story/_/id/17547270/acc-moving-neutral-site-championship-games-north-carolina-due-hb2", "meta"=>{"accessed"=>"9/17/16", "author"=>"Andrea Adelson", "date"=>"9/15/16", "publication"=>"ESPN", "title"=>"ACC moving neutral-site championship games out of North Carolina due to HB2"}}, {"link"=>"http://www.charlotteobserver.com/sports/college/article101788782.html", "meta"=>{"accessed"=>"9/17/16", "author"=>"Rick Rothacker and Katherine Peralta", "date"=>"9/14/16", "publication"=>"Charlotte Observer", "title"=>"ACC pulls football title game from Charlotte over HB2"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "Atlantic Coast Conference", photo_credit: ""},
  {date: "2016-09-12 04:00:00", amount: "0.0", title: "NCAA relocates 2016-17 championships out of NC in response to HB2", slug: "ncaa", description: "", template: "\nThings just keep getting worse for the state of NC over HB2.<br><br>\n\nAccounting for nearly 0% of the total losses to the state of North Carolina to date, the  loss of this event is a painful reality for the state.\n\n <blockquote class=\"template-quote\">\n\"\"Fairness is about more than the opportunity to participate in college sports, or even compete for championships.\"\n<br><br>\n- Mark Emmert, President, NCAA.\n <a class=\"link\" href=\"http://www.ncaa.org/about/resources/media-center/news/ncaa-relocate-championships-north-carolina-2016-17\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe loss of the NCAA is just one of many recent HB2 related economic downfalls affecting the state of North Carolina.\n", sources: [{"link"=>"http://www.nytimes.com/2016/09/13/sports/ncaa-moves-championship-events-from-north-carolina.html?_r=0", "meta"=>{"accessed"=>"9/17/16", "author"=>"Marc Tracy and Alan Blinder", "date"=>"9/12/16", "publication"=>"New York Times", "title"=>"N.C.A.A. Moves Championship Events From North Carolina, Citing Anti-Gay-Rights Law"}}, {"link"=>"http://www.usatoday.com/story/sports/college/2016/09/12/ncaa-to-relocate-championship-events-north-carolina-house-bill-2/90284584/", "meta"=>{"accessed"=>"9/17/16", "author"=>"Scott Gleeson", "date"=>"9/12/16", "publication"=>"USA Today", "title"=>"NCAA to move 7 championships from North Carolina due to HB2 law"}}, {"link"=>"http://edition.cnn.com/2016/09/12/sport/ncaa-pulls-championships-north-carolina-lgbtq/", "meta"=>{"accessed"=>"9/17/16", "author"=>"Steve Visser", "date"=>"9/13/16", "publication"=>"CNN", "title"=>"NCAA pulls championships from North Carolina over LGBT law"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "National Collegiate Athletic Association", photo_credit: "Al Sermeno Photography / Shutterstock.com"},
  {date: "2016-08-23 04:00:00", amount: "0.0", title: "Russell Wilson and Ciara moved wedding out of NC because of HB2", slug: "russell-wilson-ciara", description: "", template: "\nThe state of North Carolina reports another loss due to HB2.<br><br>\n\nAccounting for nearly 0% of the total losses to the state of North Carolina to date, the  loss of this event is but one of many recent hits related to HB2.\n\n <blockquote class=\"template-quote\">\n\"\"They were first getting married in North Carolina, but they called it off due to the transgender bathroom laws.\"\n<br><br>\n- Mindy Weiss, Wedding planner for the couple.\n <a class=\"link\" href=\"\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe Russell Wilson and Ciara wedding in  is just one of recent losses for NC over HB2.\n", sources: [{"link"=>"http://edition.cnn.com/2016/08/23/sport/russell-wilson-ciara-wedding-moved-north-carolina-transgender-bathroom-law/", "meta"=>{"accessed"=>"9/17/16", "author"=>"Jill Martin", "date"=>"8/23/16", "publication"=>"CNN", "title"=>"Russell Wilson, Ciara moved wedding due to NC transgender law"}}, {"link"=>"http://www.newsobserver.com/news/politics-government/politics-columns-blogs/under-the-dome/article97308942.html", "meta"=>{"accessed"=>"9/17/16", "author"=>"Katherine Peralta", "date"=>"8/23/16", "publication"=>"News and Observer", "title"=>"Russell Wilson, Ciara moved their July wedding from N.C. because of HB2"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "Russell Wilson and Ciara", photo_credit: "Featureflash Photo Agency / Shutterstock.com"},
  {date: "2016-04-21 04:00:00", amount: "183000.0", title: "The National Organization for Victim Assistance cancels a training event in Charlotte in opposition to HB2", slug: "nova", description: "", template: "\nNorth Carolina bears the burden of more economic strain over HB2, the controversial \"bathroom bill\" law.<br><br>\n\nAccounting for nearly 0% of the total losses to the state of North Carolina to date, the  loss of this training event is but one of many recent hits related to HB2.\n\n <blockquote class=\"template-quote\">\n\"\"\"\n<br><br>\n- \n</blockquote>\n\nThe state continues to lose money over HB2.\n", sources: [{"link"=>"http://www.wral.com/news/local/page/15643947/", "meta"=>{"accessed"=>"9/14/16", "publication"=>"WRAL", "title"=>"At a glance: Economic impacts of HB2"}}, {"link"=>"http://www.charlotteobserver.com/news/business/article73023232.html", "meta"=>{"accessed"=>"9/14/16", "publication"=>"Charlotte Observer", "title"=>"Victim assistance organization cancels Charlotte event because of LGBT law", "date"=>"4/21/16", "author"=>"Katherine Peralta"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "National Organization for Victim Assistance", photo_credit: ""},
  {date: "2016-05-17 04:00:00", amount: "230000.0", title: "NCLR Cancels moves it's 2016 conference from Raleigh to Miami in protest over HB2", slug: "nclr", description: "", template: "\nNC continues to lose money due to the controversial House Bill 2.<br><br>\n\nContributing  $230,000 to the total of $259,424,000, the loss of this conference hurts North Carolina.\n\n <blockquote class=\"template-quote\">\n\"\"By taking this action, we extend our support to the efforts of so many in North Carolina and the LGBT, civil rights and business communities to repeal this egregious law.\"\n<br><br>\n- Janet Murguía, NCLR President and CEO.\n <a class=\"link\" href=\"http://www.nclr.org/about-us/media/press/releases/NCLR-Press-Statement-NC-LGBT-051716\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe loss of the National Council of La Raza is not only a loss for Raleigh, but for the state of North Carolina as a whole.\n", sources: [{"link"=>"http://www.wral.com/news/local/page/15643947/", "meta"=>{"accessed"=>"9/14/16", "publication"=>"WRAL", "title"=>"At a glance: Economic impacts of HB2"}}, {"link"=>"http://www.glaad.org/blog/nations-largest-latino-organization-cancels-nc-event-protest-anti-lgbt-law", "meta"=>{"accessed"=>"9/14/16", "publication"=>"GLAAD", "title"=>"Nation's largest Latino organization cancels NC event to protest anti-LGBT law", "date"=>"5/17/16", "author"=>"Richard Allen"}}], active: true, featured: false, short_name: "National Council of La Raza", photo_credit: ""},
  {date: "2016-07-24 04:00:00", amount: "0.0", title: "UVM cancels UNC women's basketball game over HB2", slug: "uvm-vs-unc", description: "", template: "\nThe state of North Carolina reports another loss due to HB2.<br><br>\n\nContributing  $0 to the total of $259,424,000, the loss of this event is painful for NC.\n\n <blockquote class=\"template-quote\">\n\"\"The decision to cancel to our Dec. 28 women's basketball game at North Carolina was made as a result of concerns over the HB2 law, which prevents transgender people from using government-run bathrooms based on their gender identity.\"\n<br><br>\n- Jeff Schulman, Athletic Director, UVM.\n <a class=\"link\" href=\"\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThis is but one of many recent losses for the state of NC related to HB2.\n", sources: [{"link"=>"http://www.burlingtonfreepress.com/story/sports/college/vermont/2016/08/24/uvm-cancels-basketball-game-unc/89303284/", "meta"=>{"accessed"=>"9/17/16", "author"=>"Alex Abrami and Austin Danforth", "date"=>"8/24/16", "publication"=>"Burlington Free Press", "title"=>"UVM cancels basketball game at UNC over HB2 law"}}, {"link"=>"http://www.cbssports.com/college-basketball/news/womens-basketball-game-at-north-carolina-canceled-over-hb2-bathroom-bill/", "meta"=>{"accessed"=>"9/17/16", "author"=>"Chip Patterson", "date"=>"8/25/16", "publication"=>"CBS Sports", "title"=>"Women's basketball game at North Carolina canceled over HB2 'bathroom bill'"}}, {"link"=>"CUSTOM_CALC"}], active: true, featured: false, short_name: "University of Vermont ", photo_credit: "Debby Wong / Shutterstock.com\n"},
  {date: "2016-04-22 04:00:00", amount: "57000.0", title: "Citing HB2 travel bans, IASIR moves fall conference to Vegas", slug: "iasir", description: "", template: "\nHere's another unfortunate loss for the state of North Carolina.<br><br>\n\nAccounting for nearly 0% of the total losses to the state of North Carolina to date, the  loss of this conference is yet another financial setback for the state over HB2.\n\n <blockquote class=\"template-quote\">\n\"\"\"\n<br><br>\n- \n</blockquote>\n\nThe loss of the International Association of Security & Investigative Regulators is just one of many recent HB2 related economic downfalls affecting the state of North Carolina.\n", sources: [{"link"=>"http://www.wral.com/news/local/page/15643947/", "meta"=>{"accessed"=>"9/14/16", "publication"=>"WRAL", "title"=>"At a glance: Economic impacts of HB2"}}, {"link"=>"http://www.tradeshowexecutive.com/archive/industry-news/north-carolina-lgbt-turmoil-continues-costs-state-group-business/", "meta"=>{"accessed"=>"9/14/16", "author"=>"Sandi Cain", "date"=>"4/22/16", "publication"=>"Trade Show Executive", "title"=>"North Carolina LGBT Turmoil Continues, Costs State Group Business"}}], active: true, featured: false, short_name: "International Association of Security & Investigative Regulators", photo_credit: ""}
